/**
 * Rebuilds the search index for one organization; used after a bulk import or an index drift alarm.
 *
 * Must call (do not reimplement): indexIssue, indexComment, indexProject
 */
import { createLogger } from "@/lib/logger";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import {
  indexComment,
  indexIssue,
  indexProject,
} from "@/server/services/search-service";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { OrgId, Page } from "@/types/common";

/** Rows read per page while walking the org's content. */
const PAGE_SIZE = 100;

const logger = createLogger("search-reindex-job");

/**
 * Walks one tenant's projects, issues and comments and re-upserts every
 * document the visibility rule allows. Scoped to a single org on purpose: a
 * full-fleet reindex is a sequence of these, so one slow tenant cannot stall
 * the rest.
 *
 * Only live rows are handed to the index writers, and rows of this org that
 * the rule no longer allows are pruned first, so the rebuild leaves exactly
 * the searchable entries. Every listing is walked to its last page, so large
 * workspaces are not truncated.
 */
export async function runSearchReindexJob(orgId: OrgId): Promise<JobResult> {
  return runJob("search-reindex", async (result) => {
    await searchRepo.pruneUnsearchable(orgId);

    const liveProjectIds = new Set<string>();
    for await (const project of eachItem((cursor) =>
      projectRepo.listProjects({
        orgId,
        limit: PAGE_SIZE,
        cursor,
        includeArchived: false,
      }),
    )) {
      liveProjectIds.add(project.id);
      try {
        await indexProject(orgId, project);
        result.processed += 1;
      } catch (error) {
        result.failed += 1;
        logger.error("failed to index project", {
          projectId: project.id,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }

    for await (const issue of eachItem((cursor) =>
      issueRepo.listIssues({
        orgId,
        limit: PAGE_SIZE,
        cursor,
        includeArchived: false,
      }),
    )) {
      if (!liveProjectIds.has(issue.projectId)) continue;

      try {
        await indexIssue(orgId, issue);
        result.processed += 1;

        for await (const comment of eachItem((cursor) =>
          commentRepo.listComments({
            orgId,
            issueId: issue.id,
            includeArchived: false,
            limit: PAGE_SIZE,
            cursor,
          }),
        )) {
          await indexComment(orgId, comment);
          result.processed += 1;
        }
      } catch (error) {
        result.failed += 1;
        logger.error("failed to index issue", {
          issueId: issue.id,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}

/** Yields every row of a keyset-paginated listing, page after page. */
async function* eachItem<T>(
  fetchPage: (cursor: string | null) => Promise<Page<T>>,
): AsyncGenerator<T> {
  let cursor: string | null = null;
  do {
    const page = await fetchPage(cursor);
    for (const item of page.items) yield item;
    cursor = page.nextCursor;
  } while (cursor !== null);
}
